on conflict (id) do update set
  production_date=excluded.production_date,product_code=excluded.product_code,product_name=excluded.product_name,
  width_mm=excluded.width_mm,length_mm=excluded.length_mm,thickness_mm=excluded.thickness_mm,
  plan_qty=excluded.plan_qty,note=excluded.note,order_group=excluded.order_group,source_order_id=excluded.source_order_id,
  is_manual=excluded.is_manual,is_drop=excluded.is_drop,is_ghost=excluded.is_ghost,is_warranty=excluded.is_warranty,
  is_lot=excluded.is_lot,lot_label=excluded.lot_label,source_payload=excluded.source_payload,
  deleted_at=null,cancel_reason=null,cancelled_by=null,updated_at=now();
on conflict (order_id) do update set plan_team=excluded.plan_team,current_team=excluded.current_team,
  change_note=excluded.change_note,updated_at=now();
on conflict (order_id,work_date,stage) do update set quantity=excluded.quantity,kpi_team=excluded.kpi_team,
  entered_by=null,completed_by_worker_id=excluded.completed_by_worker_id,updated_at=now();
on conflict (order_id,work_date,stage,worker_id) do update set quantity=excluded.quantity,source=excluded.source,updated_at=now();
do $$
declare bad text;
begin
  if (select count(*) from public.khsx_orders where production_date between date '2026-08-25' and date '2026-08-29' and deleted_at is null) <> 100 then
    raise exception 'Sai tong so don KHSX 25-29/08: khong dung 100';
  end if;

  with expected(production_date,cnt,qty) as (values
    (date '2026-08-25',26,168),
    (date '2026-08-26',22,169),
    (date '2026-08-27',16,102),
    (date '2026-08-28',19,95),
    (date '2026-08-29',17,108)
  ), actual as (
    select production_date,count(*)::int cnt,sum(plan_qty)::int qty from public.khsx_orders
    where deleted_at is null and production_date between date '2026-08-25' and date '2026-08-29' group by production_date
  )
  select string_agg(e.production_date||': cnt '||coalesce(a.cnt,0)||'!='||e.cnt||' or qty '||coalesce(a.qty,0)||'!='||e.qty,', ')
  into bad from expected e left join actual a using(production_date) where coalesce(a.cnt,0)<>e.cnt or coalesce(a.qty,0)<>e.qty;
  if bad is not null then raise exception 'Sai so don/so luong theo ngay: %',bad; end if;

  with expected(work_date,stage,qty) as (values
    (date '2026-08-25','dan'::public.khsx_stage,138),
    (date '2026-08-25','may'::public.khsx_stage,133),
    (date '2026-08-25','dong_goi'::public.khsx_stage,131),
    (date '2026-08-26','dan'::public.khsx_stage,184),
    (date '2026-08-26','may'::public.khsx_stage,189),
    (date '2026-08-26','dong_goi'::public.khsx_stage,189),
    (date '2026-08-27','dan'::public.khsx_stage,102),
    (date '2026-08-27','may'::public.khsx_stage,102),
    (date '2026-08-27','dong_goi'::public.khsx_stage,102),
    (date '2026-08-28','dan'::public.khsx_stage,95),
    (date '2026-08-28','may'::public.khsx_stage,95),
    (date '2026-08-28','dong_goi'::public.khsx_stage,95),
    (date '2026-08-29','dan'::public.khsx_stage,108),
    (date '2026-08-29','may'::public.khsx_stage,108),
    (date '2026-08-29','dong_goi'::public.khsx_stage,108)
  ), actual as (
    select work_date,stage,sum(quantity)::int qty from public.khsx_stage_progress
    where work_date between date '2026-08-25' and date '2026-08-29' group by work_date,stage
  )
  select string_agg(e.work_date||'/'||e.stage||': '||coalesce(a.qty,0)||' != '||e.qty,', ')
  into bad from expected e left join actual a using(work_date,stage) where coalesce(a.qty,0)<>e.qty;
  if bad is not null then raise exception 'Sai tong tien do cong doan: %',bad; end if;

  if (select count(*) from public.khsx_order_assignments a join public.khsx_orders o on o.id=a.order_id where o.production_date between date '2026-08-25' and date '2026-08-29') <> 61 then
    raise exception 'Sai so dong khsx_order_assignments';
  end if;

  if (select count(*) from public.khsx_stage_credits where work_date between date '2026-08-25' and date '2026-08-29') <> 89 then
    raise exception 'Sai so dong khsx_stage_credits';
  end if;
end $$;
commit;
